sealed class AdminAccount {
 public long AccountId,CreatedUtc,LastActiveUtc,DeviceCount; public string Username="";public bool Online;
 static string When(long value){if(value<=0)return "Never";return new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddSeconds(value).ToLocalTime().ToString("g");}
 public override string ToString(){return "@"+Username+"  ·  ID "+AccountId+"\n"+(Online?"● Online":"○ Offline")+"  ·  Created "+When(CreatedUtc)+"  ·  Last active "+When(LastActiveUtc)+"  ·  "+DeviceCount+" device"+(DeviceCount==1?"":"s");}
}
