 static FrameworkElement CacheSettings(AttachmentCacheConfiguration value,out Action save){
  var body=new StackPanel();body.Children.Add(new TextBlock{Text="Configuration preview — encrypted cache endpoints are not enabled in this candidate. Saving does not initialize, move or delete storage. Changes apply on server restart; migration requires the explicit runbook.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,12)});
  var labels=new[]{"Maximum cache capacity (bytes)","Retention after upload (seconds)","Partial inactivity expiry (seconds)","Minimum free space (bytes)","Minimum free space (percent)","Absolute cache directory","Expected filesystem identity","Expected mount point","Cache instance ID"};
  var values=new[]{value.MaximumBytes.ToString(),value.RetentionSeconds.ToString(),value.PartialIdleSeconds.ToString(),value.MinimumFreeBytes.ToString(),value.MinimumFreePercent.ToString(),value.Directory,value.ExpectedFilesystem,value.ExpectedMountPoint,value.InstanceId};
  var fields=values.Select(v=>new TextBox{Text=v,Margin=new Thickness(0,4,0,10)}).ToArray();
  for(int i=0;i<fields.Length;i++){body.Children.Add(new TextBlock{Text=labels[i]});body.Children.Add(fields[i]);}
  save=()=>{long capacity,retention,idle,free;int percent;
   if(!Int64.TryParse(fields[0].Text,out capacity)||!Int64.TryParse(fields[1].Text,out retention)||!Int64.TryParse(fields[2].Text,out idle)||!Int64.TryParse(fields[3].Text,out free)||!Int32.TryParse(fields[4].Text,out percent))throw new InvalidOperationException("Cache sizes and retention must be whole numbers; capacity is not the individual 256 MiB file limit.");
   var candidate=new AttachmentCacheConfiguration{Enabled=value.Enabled,MaximumBytes=capacity,RetentionSeconds=retention,PartialIdleSeconds=idle,MinimumFreeBytes=free,MinimumFreePercent=percent,Directory=fields[5].Text.Trim(),ExpectedFilesystem=fields[6].Text.Trim(),ExpectedMountPoint=fields[7].Text.Trim(),InstanceId=fields[8].Text.Trim()};candidate.Validate();
   value.MaximumBytes=candidate.MaximumBytes;value.RetentionSeconds=candidate.RetentionSeconds;value.PartialIdleSeconds=candidate.PartialIdleSeconds;value.MinimumFreeBytes=candidate.MinimumFreeBytes;value.MinimumFreePercent=candidate.MinimumFreePercent;value.Directory=candidate.Directory;value.ExpectedFilesystem=candidate.ExpectedFilesystem;value.ExpectedMountPoint=candidate.ExpectedMountPoint;value.InstanceId=candidate.InstanceId;
  };
  return new Expander{Header="Encrypted attachment cache · staged configuration",Content=body,Foreground=Brush("#EDF1F5"),Margin=new Thickness(0,8,0,12)};
 }
