 void ShowSettings(bool firstRun){var dialog=new Window{Title=firstRun?"First-Time Server Setup":"Server Settings",Owner=this,Width=560,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Brush("#101820"),Foreground=Brush("#EDF1F5"),FontFamily=new FontFamily("Segoe UI")};var panel=new StackPanel{Margin=new Thickness(24)};dialog.MaxHeight=800;dialog.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};panel.Children.Add(Label(firstRun?"Configure PeerChat Server":"Server Settings",24));panel.Children.Add(new TextBlock{Text="The development certificate is created or reused automatically. Changes take effect on the next server start.",Foreground=Brush("#A1AEBB"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,16)});var data=new TextBox{Text=config.DataDirectory};var address=new TextBox{Text=config.ListenAddress};var port=new TextBox{Text=config.Port.ToString()};var publicHost=new TextBox{Text=config.PublicHostname};var p2pHost=new TextBox{Text=config.SelfHostedPublicP2PHost};var database=new TextBox{Text=config.DatabasePath};var logs=new TextBox{Text=config.LogDirectory};var labels=new[]{"Server data location","Listen address","Discovery TLS port","Public discovery service hostname/IP","Self-hosted public P2P address (optional)","Database location","Log location"};var fields=new TextBox[]{data,address,port,publicHost,p2pHost,database,logs};for(int i=0;i<fields.Length;i++){panel.Children.Add(new TextBlock{Text=labels[i],Margin=new Thickness(0,0,0,5)});fields[i].Margin=new Thickness(0,0,0,12);panel.Children.Add(fields[i]);}var turnEnabled=new CheckBox{Content="Enable TURN media credential issuer (UDP only)",IsChecked=config.TurnEnabled,Foreground=Brush("#EDF1F5"),Margin=new Thickness(0,4,0,8)};var turnHost=new TextBox{Text=config.TurnPublicHost};var turnPort=new TextBox{Text=config.TurnUdpPort.ToString()};var turnTtl=new TextBox{Text=config.TurnCredentialTtlSeconds.ToString()};var turnRealm=new TextBox{Text=config.TurnRealm};var turnSecret=new PasswordBox{ToolTip="Leave blank to keep the existing protected secret"};panel.Children.Add(turnEnabled);var turnLabels=new[]{"TURN public host","TURN UDP port","TURN credential TTL (seconds)","TURN realm","TURN REST shared secret (leave blank to keep current)"};var turnFields=new FrameworkElement[]{turnHost,turnPort,turnTtl,turnRealm,turnSecret};for(int i=0;i<turnFields.Length;i++){panel.Children.Add(new TextBlock{Text=turnLabels[i],Margin=new Thickness(0,0,0,5)});turnFields[i].Margin=new Thickness(0,0,0,12);panel.Children.Add(turnFields[i]);}panel.Children.Add(new TextBlock{Text="The shared secret is protected for this Windows server user and is never displayed, logged, or sent to clients.",Foreground=Brush("#A1AEBB"),TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)});Action saveCache;panel.Children.Add(CacheSettings(config.AttachmentCache,out saveCache));var regenerate=Button("Regenerate Development Certificate",()=>{if(MessageBox.Show("Clients trusting the current fingerprint will reject the new server certificate. Continue?","Regenerate certificate",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes)PrepareCertificate(true);});regenerate.Margin=new Thickness(0,0,0,12);panel.Children.Add(regenerate);var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var cancel=Button("Cancel",()=>dialog.DialogResult=false);var save=Button("Save Configuration",()=>{int selectedPort,selectedTurnPort,selectedTurnTtl;if(!Int32.TryParse(port.Text,out selectedPort)){MessageBox.Show("TLS port must be a number.");return;}if(!Int32.TryParse(turnPort.Text,out selectedTurnPort)||!Int32.TryParse(turnTtl.Text,out selectedTurnTtl)){MessageBox.Show("TURN port and credential TTL must be numbers.");return;}config.DataDirectory=data.Text.Trim();config.ListenAddress=address.Text.Trim();config.Port=selectedPort;config.PublicHostname=publicHost.Text.Trim();config.SelfHostedPublicP2PHost=p2pHost.Text.Trim();config.DatabasePath=database.Text.Trim();config.LogDirectory=logs.Text.Trim();config.TurnEnabled=turnEnabled.IsChecked==true;config.TurnPublicHost=turnHost.Text.Trim();config.TurnUdpPort=selectedTurnPort;config.TurnCredentialTtlSeconds=selectedTurnTtl;config.TurnRealm=turnRealm.Text.Trim();if(!String.IsNullOrWhiteSpace(turnSecret.Password))config.SetTurnRestSharedSecret(turnSecret.Password);try{saveCache();config.Validate();config.Save(configPath);dialog.DialogResult=true;}catch(Exception error){MessageBox.Show(error.Message,"Invalid configuration");}} ,new Thickness(8,0,0,0));actions.Children.Add(cancel);actions.Children.Add(save);panel.Children.Add(actions);dialog.ShowDialog();}
 async Task PrepareCertificate(bool forceNew=false){try{var cert=forceNew?null:FindCertificate();if(cert==null){Append("INFO  Creating/reusing the development TLS certificate.");cert=CreateDevelopmentCertificate();}if(cert==null)throw new InvalidOperationException("Windows could not create or store the development certificate.");using(var hash=SHA256.Create())certificatePin=BitConverter.ToString(hash.ComputeHash(cert.GetRawCertData())).Replace("-","");config.CertificateThumbprint=cert.Thumbprint;config.Save(configPath);details.Text="TLS ready\nSHA-256: "+certificatePin;Append("INFO  Development TLS certificate ready. Configuration saved to "+configPath);}catch(Exception error){details.Text="TLS setup failed: "+error.Message;Append("ERROR Certificate setup failed: "+error.GetType().Name+": "+error.Message);}}
 // CertificateRequest avoids relying on the PowerShell certificate cmdlet or its enrollment
 // dependencies. The private key is generated and retained by Windows in CurrentUser\My; only
 // the public certificate thumbprint is persisted in PeerChat configuration.
 X509Certificate2 CreateDevelopmentCertificate(){using(var key=RSA.Create(2048)){var request=new CertificateRequest("CN=PeerChat Development Discovery Server",key,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);request.CertificateExtensions.Add(new X509BasicConstraintsExtension(false,false,0,false));request.CertificateExtensions.Add(new X509KeyUsageExtension(X509KeyUsageFlags.DigitalSignature|X509KeyUsageFlags.KeyEncipherment,false));var temporary=request.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-5),DateTimeOffset.UtcNow.AddYears(1));var persisted=new X509Certificate2(temporary.Export(X509ContentType.Pfx),"",X509KeyStorageFlags.UserKeySet|X509KeyStorageFlags.PersistKeySet|X509KeyStorageFlags.Exportable);var store=new X509Store(StoreName.My,StoreLocation.CurrentUser);store.Open(OpenFlags.ReadWrite);try{store.Add(persisted);}finally{store.Close();}return persisted;}}
 X509Certificate2 FindCertificate(){var store=new X509Store(StoreName.My,StoreLocation.CurrentUser);store.Open(OpenFlags.ReadOnly);try{X509Certificate2 newest=null;foreach(X509Certificate2 cert in store.Certificates)if(cert.Subject=="CN=PeerChat Development Discovery Server"&&cert.HasPrivateKey&&cert.NotAfter>DateTime.Now.AddDays(7)&&(newest==null||cert.NotBefore>newest.NotBefore))newest=cert;return newest;}finally{store.Close();}}
 async Task Start(){if(server!=null&&!server.HasExited)return;if(String.IsNullOrEmpty(certificatePin))await PrepareCertificate();if(String.IsNullOrEmpty(certificatePin)){Append("ERROR TLS setup is required before starting.");return;}pipeName="PeerChatAdmin-"+Guid.NewGuid().ToString("N");config.Save(configPath);var arguments="--config \""+configPath+"\" --management-pipe "+pipeName;var start=new ProcessStartInfo(serverPath,arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};server=new Process{StartInfo=start,EnableRaisingEvents=true};server.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Dispatcher.BeginInvoke(new Action(()=>Append(e.Data)));};server.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Dispatcher.BeginInvoke(new Action(()=>Append("ERROR "+e.Data)));};server.Exited+=(s,e)=>Dispatcher.BeginInvoke(new Action(()=>{Append("INFO  Server process exited.");state.Text="Stopped";statusTimer.Stop();}));server.Start();server.BeginOutputReadLine();server.BeginErrorReadLine();Append("INFO  Starting headless PeerChat.Server using "+configPath);statusTimer.Start();await Task.Delay(400);await RefreshStatus();await LoadAccounts(true);}
 async Task Stop(){if(server==null||server.HasExited){state.Text="Stopped";return;}try{await Task.Run(()=>Command("STOP"));if(!server.WaitForExit(7000)){Append("WARNING Graceful shutdown was accepted but did not finish within seven seconds; the server is still running.");return;}Append("INFO  Server stopped gracefully.");}catch(Exception error){Append("ERROR Graceful shutdown command could not reach the local management pipe: "+error.Message+". The listener may still be running.");}finally{statusTimer.Stop();state.Text=server.HasExited?"Stopped":"Running · stop not confirmed";}}
 string Command(string command){using(var pipe=new NamedPipeClientStream(".",pipeName,PipeDirection.InOut)){pipe.Connect(1500);var encoding=new UTF8Encoding(false);var writer=new StreamWriter(pipe,encoding,256,true);var reader=new StreamReader(pipe,encoding,false,256,true);writer.WriteLine(command);writer.Flush();var response=reader.ReadLine();if(String.IsNullOrEmpty(response))throw new IOException("The server closed the management pipe without a response");return response;}}
 string Prompt(string title,string instruction){var dialog=new Window{Title=title,Owner=this,Width=520,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Brush("#101820"),Foreground=Brush("#EDF1F5"),FontFamily=new FontFamily("Segoe UI")};var panel=new StackPanel{Margin=new Thickness(24)};dialog.Content=panel;panel.Children.Add(new TextBlock{Text=instruction,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)});var value=new TextBox{MinWidth=440};panel.Children.Add(value);var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,16,0,0)};var cancel=Button("Cancel",()=>dialog.DialogResult=false);var ok=Button("Continue",()=>dialog.DialogResult=true,new Thickness(8,0,0,0));actions.Children.Add(cancel);actions.Children.Add(ok);panel.Children.Add(actions);dialog.Loaded+=(s,e)=>value.Focus();return dialog.ShowDialog()==true?value.Text.Trim():null;}
 async Task LoadAccounts(bool reset){if(server==null||server.HasExited||accountSearch==null)return;int generation=reset?++accountSearchGeneration:accountSearchGeneration,offset=reset?0:accountOffset;string query=accountSearch.Text??"";try{string command="ACCOUNT_LIST "+offset+" "+AccountPageSize+" "+Convert.ToBase64String(Encoding.UTF8.GetBytes(query));var response=await Task.Run(()=>json.Deserialize<Dictionary<string,object>>(Command(command)));if(generation!=accountSearchGeneration)return;object ok,raw;if(!response.TryGetValue("ok",out ok)||!(bool)ok||!response.TryGetValue("accounts",out raw))throw new InvalidOperationException("Server refused account search.");if(reset)accountResults.Items.Clear();int added=0;foreach(object item in raw as ArrayList??new ArrayList()){var row=item as Dictionary<string,object>;if(row==null)continue;accountResults.Items.Add(new AdminAccount{AccountId=Convert.ToInt64(row["accountId"]),Username=row["username"] as string??"",CreatedUtc=Convert.ToInt64(row["createdUtc"]),LastActiveUtc=Convert.ToInt64(row["lastActiveUtc"]),Online=Convert.ToBoolean(row["online"]),DeviceCount=Convert.ToInt64(row["deviceCount"])});added++;}accountOffset=offset+added;bool more=response.ContainsKey("hasMore")&&Convert.ToBoolean(response["hasMore"]);accountLoadMore.Visibility=more?Visibility.Visible:Visibility.Collapsed;accountHint.Text=String.IsNullOrWhiteSpace(query)?"Newest and recently active accounts":"Matching accounts for \""+query+"\"";}catch(Exception error){if(generation==accountSearchGeneration){accountHint.Text="Account list unavailable";Append("WARNING Account browse failed: "+error.GetType().Name+": "+error.Message);}}}
 async Task DeleteAccount(){if(server==null||server.HasExited){MessageBox.Show(this,"Start the server before using local account administration.","PeerChat Server Admin");return;}var selected=accountResults==null?null:accountResults.SelectedItem as AdminAccount;if(selected==null){MessageBox.Show(this,"Select one account from Recent / Matching Accounts first.","PeerChat Server Admin");return;}try{string phrase="DELETE "+selected.AccountId;string warning="Delete account \""+selected.Username+"\"?\n\nStable account ID: "+selected.AccountId+"\n\nThis removes the server account, password/session records, registered devices, presence, server friend/request/block records, and active relay attachments. "+(selected.Online?"The account is online and will be disconnected immediately. ":"")+"It cannot delete local PeerChat history or profiles.\n\nType exactly: "+phrase;string confirmation=Prompt("Delete account \""+selected.Username+"\"?",warning);if(!String.Equals(confirmation,phrase,StringComparison.Ordinal)){MessageBox.Show(this,"Account deletion cancelled: confirmation text did not match.","PeerChat Server Admin");return;}if(MessageBox.Show(this,"Delete account \""+selected.Username+"\" (ID "+selected.AccountId+") from this server? The username will become available for a new account.","Final account deletion confirmation",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;var result=await Task.Run(()=>json.Deserialize<Dictionary<string,object>>(Command("DELETE_ACCOUNT "+selected.AccountId)));object ok;if(!result.TryGetValue("ok",out ok)||!(bool)ok)throw new InvalidOperationException("Server refused account deletion; the selected account may already be gone.");Append("WARNING Account @"+selected.Username+" (ID "+selected.AccountId+") was deleted from server administration.");MessageBox.Show(this,"Server account @"+selected.Username+" (ID "+selected.AccountId+") was deleted. Existing client profiles and encrypted local history were not changed.","PeerChat Server Admin");await LoadAccounts(true);await RefreshStatus();}catch(Exception error){Append("ERROR Account deletion failed: "+error.GetType().Name+": "+error.Message);MessageBox.Show(this,"Could not delete the selected server account. See the admin console for details.","PeerChat Server Admin");}}
 async Task RefreshStatus(){if(server==null||server.HasExited)return;try{var raw=await Task.Run(()=>Command("STATUS"));var data=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(raw);managementUnavailable=false;state.Text="● Running";details.Text="Local listener: 0.0.0.0:"+data["port"]+"\nPublic service endpoint: "+config.PublicHostname+":"+data["port"]+"\nSHA-256: "+certificatePin;metrics.Text="Connected clients: "+data["connectedClients"]+"\nAuthenticated sessions: "+data["sessions"]+"\nPresent users: "+data["present"]+"\nRegistered accounts: "+data["accounts"]+"\nUptime: "+TimeSpan.FromSeconds(Convert.ToDouble(data["uptimeSeconds"])).ToString(@"d\.hh\:mm\:ss");bool enabled=data.ContainsKey("turnEnabled")&&Convert.ToBoolean(data["turnEnabled"]);turnStatus.Text=!enabled?"Disabled\nDiscovery and relay messaging remain available.":"Enabled · UDP credentials only\nHost: "+data["turnHost"]+":"+data["turnUdpPort"]+"\nCredential TTL: "+data["turnCredentialTtlSeconds"]+" seconds";}catch(Exception error){state.Text="● Running · monitoring unavailable";if(!managementUnavailable){managementUnavailable=true;Append("WARNING Local management status unavailable: "+error.Message);}}}
 async void CopyPin(){if(String.IsNullOrEmpty(certificatePin)){MessageBox.Show(this,"The server certificate fingerprint is not ready yet. Wait for TLS setup to complete, then try again.","PeerChat Server Admin");return;}for(int attempt=0;attempt<6;attempt++){bool busy=false;try{Clipboard.SetText(certificatePin);Append("INFO Server TLS SHA-256 fingerprint copied to the clipboard.");return;}catch(ExternalException){busy=true;}if(busy)await Task.Delay(100);}Append("WARNING Server TLS fingerprint could not be copied because the Windows clipboard stayed busy.");MessageBox.Show(this,"Windows clipboard is busy. Close the application currently using it and try Copy Fingerprint again.","PeerChat Server Admin");} void Append(string text){string next=DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine;console.AppendText(next);if(console.Text.Length>MaxConsoleCharacters)console.Text=console.Text.Substring(console.Text.Length-MaxConsoleCharacters);if(autoScroll.IsChecked==true)console.ScrollToEnd();}
 void OnClosing(object sender,System.ComponentModel.CancelEventArgs e){if(allowClose||server==null||server.HasExited)return;var choice=MessageBox.Show("The headless server is still running.\n\nYes: stop the server and exit\nNo: leave it running and close only Admin\nCancel: keep Admin open","PeerChat Server Admin",MessageBoxButton.YesNoCancel,MessageBoxImage.Question);if(choice==MessageBoxResult.Cancel){e.Cancel=true;return;}if(choice==MessageBoxResult.No){allowClose=true;return;}e.Cancel=true;Task.Run(()=>{try{Command("STOP");server.WaitForExit(7000);}catch{}Dispatcher.BeginInvoke(new Action(()=>{allowClose=true;Close();}));});}
}
class Program {[STAThread] static int Main(string[] args){var app=new Application();app.Run(new AdminWindow(args.Length==1&&args[0]=="--smoke"));return 0;}}
}
